"""Self-contained, read-only local desk panel. No CDN, telemetry or private account data."""
from __future__ import annotations

import html
import json


def render_dashboard(result):
    payload = json.dumps(result, ensure_ascii=False, default=str).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return TEMPLATE.replace("__DATA__", payload).replace("__DATE__", html.escape(result["at"]))


TEMPLATE = r'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Quantia · Desk de tesis</title><style>
:root{--paper:#f5f4ef;--ink:#172923;--muted:#596961;--line:#d2d9d1;--green:#195a3c;--amber:#835217}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,sans-serif}a{color:var(--green)}button,input,select{font:inherit}button,select,input{border:1px solid var(--line);background:#fff;padding:10px 14px;border-radius:4px;color:var(--ink)}button{cursor:pointer}button:hover{background:#e8ede5}:focus-visible{outline:3px solid #368965;outline-offset:3px}.wrap{max-width:1450px;margin:auto;padding:30px 40px}.top{border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:20px;padding-bottom:20px}.brand{font-weight:750;letter-spacing:3px}.badge{font:12px ui-monospace,monospace;letter-spacing:1px;color:var(--green);border:1px solid var(--green);padding:5px 10px}.hero{display:grid;grid-template-columns:2fr 1fr;gap:40px;margin:32px 0}.eyebrow{font:12px ui-monospace,monospace;letter-spacing:2px;text-transform:uppercase;color:var(--muted)}h1{font:clamp(36px,4vw,58px)/1.05 Georgia,serif;margin:12px 0}h2{font:28px Georgia,serif;margin:0 0 16px}h3{margin:0 0 10px;font-size:18px}p{margin:8px 0}.muted{color:var(--muted)}.notice{border-left:4px solid var(--green);padding:8px 18px;align-self:center}.metrics{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);background:#fff;margin-bottom:26px}.metric{padding:18px 22px;border-right:1px solid var(--line)}.metric:last-child{border:0}.value{font:38px Georgia,serif;display:block}.label{font-size:13px;color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.panel{background:#fff;border:1px solid var(--line);padding:24px;margin-bottom:24px}.statline{display:flex;justify-content:space-between;border-bottom:1px solid #eef0eb;padding:8px 0;gap:20px}.bar{height:8px;background:#e8ece7;margin:10px 0 20px}.bar span{display:block;height:100%;background:var(--green)}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}.toolbar input{flex:1;min-width:180px}.tablebox{overflow:auto;max-height:620px;border:1px solid var(--line)}table{width:100%;border-collapse:collapse;font-size:13px}th{position:sticky;top:0;background:#eef1eb;text-align:left;padding:12px;white-space:nowrap}td{padding:12px;border-top:1px solid var(--line);vertical-align:top}td:nth-child(1){font-weight:750;white-space:nowrap}.reason{max-width:300px;color:var(--muted);font-size:12px}.state{white-space:nowrap;color:var(--green)}.warn{color:var(--amber)}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}.idea{padding:18px;border:1px solid var(--line);background:#fafbf8}.idea p{font-size:13px}details{margin-top:14px}summary{cursor:pointer;color:var(--green)}footer{font-size:12px;color:var(--muted);padding:12px 0 30px}code{font:12px ui-monospace,monospace;overflow-wrap:anywhere}.skip{position:absolute;left:-9999px}.skip:focus{left:12px;top:12px;background:white;padding:10px;z-index:5}.empty{padding:20px;border:1px dashed var(--line);color:var(--muted)}@media(max-width:800px){.wrap{padding:20px}.hero,.grid{grid-template-columns:1fr;gap:16px}.metrics{grid-template-columns:1fr 1fr}.metric{border-bottom:1px solid var(--line)}.top{align-items:flex-start}.toolbar button{width:100%}h1{font-size:40px}}
</style></head><body><a href="#universe" class="skip">Ir al universo</a><main class="wrap">
<header class="top"><div class="brand">QUANTIA / RESEARCH DESK</div><span class="badge">PAPER · CAPITAL FICTICIO</span></header>
<section class="hero"><div><div class="eyebrow">Fuentes → revisión → riesgo → bitácora</div><h1>Todo el universo.<br>Cada decisión, visible.</h1><p class="muted">Acciones y CEDEARs registrados en Quantia, con identidad, evidencia y seguimiento.</p></div><div class="notice"><strong id="headline"></strong><p id="time"></p><p class="muted" id="model"></p><small>Esta página es una captura. Actualizá el desk y volvé a abrir el reporte para ver la siguiente corrida.</small></div></section>
<section class="metrics" aria-label="Cobertura"><div class="metric"><span class="label">Instrumentos observados</span><strong class="value" id="total"></strong></div><div class="metric"><span class="label">Acciones identificadas</span><strong class="value" id="equities"></strong></div><div class="metric"><span class="label">Fuentes completas / acciones</span><strong class="value" id="sources"></strong></div><div class="metric"><span class="label">Documentos en cola</span><strong class="value" id="queue"></strong></div></section>
<div class="grid"><section class="panel"><h2>Avance de la revisión</h2><div id="progress"></div><div class="bar" aria-hidden="true"><span id="bar"></span></div><div id="coverage"></div><details><summary>Qué cuenta como cobertura</summary><p class="muted">El denominador son las acciones identificadas. ETF, identidades faltantes y conflictos se muestran aparte. Una fuente completa es el feed acotado capturado; no significa conocimiento exhaustivo de la empresa. La revisión pendiente bloquea entradas.</p></details></section><section class="panel"><h2>Cartera paper</h2><div id="portfolio"></div><p class="muted" id="pstatus"></p><details><summary>Costos y límites de medición</summary><p>Comisión ficticia de 0,6% y deslizamiento adverso de 0,15% por lado. Sin dividendos, impuestos ni interés del efectivo. Baseline: efectivo nominal. Las pausas y marcas faltantes afectan la medición; no son ganancias verificadas de una cuenta.</p><p id="quality"></p></details></section></div>
<section class="panel"><h2>Watchlist y decisiones</h2><div id="ideas" class="cards"></div></section>
<section class="panel" id="universe"><h2>Universo completo</h2><div class="toolbar"><input id="search" type="search" aria-label="Buscar ticker o empresa" placeholder="Buscar ticker, empresa o bloqueo"><select id="filter" aria-label="Filtrar estado"><option value="">Todos los estados</option><option value="WATCHLIST">Watchlist</option><option value="QUEUED">Pendiente de revisión</option><option value="IDENTIFIED">Acciones identificadas</option><option value="EXCLUDED_ETF">ETF excluidos</option><option value="IDENTITY_UNKNOWN">Identidad faltante</option><option value="BLOCKED">Con bloqueos</option></select><button id="csv">Exportar tabla CSV</button><button id="json">Exportar métricas JSON</button></div><p class="muted" id="count" aria-live="polite"></p><div class="tablebox"><table><thead><tr><th>Ticker</th><th>Empresa / instrumento</th><th>Identidad</th><th>Fuente / documentos</th><th>Revisión</th><th>Bloqueos de entrada</th></tr></thead><tbody id="rows"></tbody></table></div></section>
<section class="panel"><h2>Resultados a 5 y 20 ruedas</h2><p class="muted">Una observación por tesis en watchlist. Rendimiento hipotético desde la primera cotización posterior: se mide separado de los fills de la cartera. Las señales sin evidencia trazable o con clasificación inválida se muestran excluidas del denominador.</p><div class="tablebox"><table><thead><tr><th>Horizonte</th><th>Cohorte válida</th><th>Excluidas</th><th>Sin precio inicial</th><th>Inmaduras</th><th>Maduras</th><th>Evaluadas</th><th>Faltantes</th><th>Retorno neto medio</th></tr></thead><tbody id="outcomes"></tbody></table></div></section>
<section class="panel"><h2>Operación y evidencia</h2><p>Ejecutar: <code>python -m scripts.run_thesis_desk --once</code></p><p>Continuar captura: <code>python -m scripts.run_thesis_desk --watch</code></p><p>Regenerar reporte sin red: <code>python -m scripts.run_thesis_desk --report</code></p><p class="muted">La cola se conserva entre corridas. Si se agota la cuota gratuita, queda pendiente; no cambia a una ruta paga. La captura debe estar activa para observar precios y stops.</p><p><a href="result.json">Resultado íntegro</a> · <a href="metrics.json">Métricas y definiciones</a> · <a href="manifest.json">Manifiesto</a></p></section>
<footer>Actualizado __DATE__. Septiembre–octubre de 2026 sigue NOT_EVALUABLE por falta de evidencia histórica. Esta captura prospectiva no reconstruye decisiones pasadas.</footer>
</main><script id="data" type="application/json">__DATA__</script><script>
const d=JSON.parse(document.getElementById('data').textContent),m=d.metrics,c=m.coverage,p=m.paper;
const el=id=>document.getElementById(id),fmt=(v,n=2)=>v===null||v===undefined?'—':Number(v).toLocaleString('es-AR',{maximumFractionDigits:n});
const set=(id,t)=>el(id).textContent=t;
set('headline',d.paper.market_state==='OPEN'?'Mercado abierto · evaluación paper':'Mercado cerrado · esperando rueda');set('time',new Date(d.at).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires',hour12:false})+' ART');set('model',d.model+' · '+d.provider);if(d.provider==='ollama')for(const code of document.querySelectorAll('code'))code.textContent=code.textContent.replace('scripts.run_thesis_desk','scripts.run_thesis_desk --local');set('total',c.observed_instruments??c.observed_symbols);set('equities',c.identified_equities);set('sources',c.source_complete+' / '+c.identified_equities);set('queue',c.pending_documents);
set('progress',c.reviewed_equities+' / '+c.identified_equities+' acciones con el feed revisado ('+fmt(c.reviewed_coverage_pct,1)+'%)');el('bar').style.width=Math.min(100,Number(c.reviewed_coverage_pct||0))+'%';
function line(parent,label,value){const row=document.createElement('div');row.className='statline';const a=document.createElement('span'),b=document.createElement('strong');a.textContent=label;b.textContent=value;row.append(a,b);parent.append(row)}
for(const [key,val] of Object.entries(c.identity_status))line(el('coverage'),({IDENTIFIED:'Identificadas',EXCLUDED_ETF:'ETF excluidos',IDENTITY_UNKNOWN:'Sin identidad suficiente',IDENTITY_CONFLICT:'Identidad en conflicto'}[key]||key),val);
line(el('coverage'),'Calendario de balances',c.earnings_calendar_covered??'—');line(el('coverage'),'Hallazgos rechazados por reglas',(d.research.rejected_findings||[]).length);line(el('coverage'),'Corridas persistidas',m.runs);line(el('coverage'),'Respuestas reutilizadas',d.research.cache_hits.length);if(d.research.budget)line(el('coverage'),'Intentos API hoy / límite',d.research.budget.attempts_today+' / '+d.research.budget.daily_limit);
for(const [label,val] of [['NAV ficticio · ARS',fmt(p.nav_ars)],['Efectivo · ARS',fmt(p.cash_ars)],['Posiciones abiertas',p.open_positions],['Fills acumulados',p.fills],['Ciclos cerrados',p.closed_cycles],['Comisiones ficticias · ARS',fmt(p.fees_ars)],['PnL realizado paper · ARS',p.fills?fmt(p.realized_pnl_ars):'—'],['Retorno total paper',p.total_return_pct===null?'—':fmt(p.total_return_pct)+'%'],['Aciertos / ciclos cerrados',p.win_rate===null?'—':fmt(Number(p.win_rate)*100)+'%']])line(el('portfolio'),label,val);
set('pstatus',p.fills?'Resultados observados de simulación; no verificados económicamente.':'Sin operaciones: aún no hay rendimiento de estrategia evaluable.');set('quality',p.quality_flags.join(' · ')||'Sin marcas de calidad registradas.');
for(const idea of d.watchlist){const card=document.createElement('article');card.className='idea';const h=document.createElement('h3');h.textContent=idea.ticker+' · '+idea.pm_decision;card.append(h);for(const text of [idea.thesis,'PM: '+idea.pm_reason,'Invalidación: '+idea.invalidation,'Zona ARS: '+fmt(idea.zone_low)+' — '+fmt(idea.zone_high),'Bloqueos: '+(idea.entry_blocks.join(', ')||'Aplican precio, cupo y riesgo')]){const para=document.createElement('p');para.textContent=text;card.append(para)}if(idea.source_url.startsWith('https://')){const a=document.createElement('a');a.href=idea.source_url;a.textContent='Ver fuente oficial';a.target='_blank';a.rel='noopener noreferrer';card.append(a)}el('ideas').append(card)}if(!d.watchlist.length){el('ideas').className='empty';set('ideas','Aún no hay candidatos decididos por PM. Revisá la cola y las fuentes antes de interpretar este resultado.');}
const sources=new Map(d.source_status.filter(x=>x.ticker).map(x=>[x.ticker,x])),queued=new Set((d.research.queue||[]).map(x=>x.ticker)),ideas=new Map(d.watchlist.map(x=>[x.ticker,x.pm_decision]));
const rows=d.catalog.map(r=>({...r,source:sources.get(r.ticker)||{},queued:queued.has(r.ticker),decision:ideas.get(r.ticker)||'',blocks:d.entry_blocks[r.ticker]||[]}));let visible=[];
function draw(){const query=el('search').value.toLowerCase(),f=el('filter').value;visible=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(query)&&(!f||(f==='WATCHLIST'?r.decision===f:f==='QUEUED'?r.queued:f==='BLOCKED'?r.blocks.length:r.status===f)));el('rows').replaceChildren();for(const r of visible){const tr=document.createElement('tr');for(const text of [r.ticker,r.name+' · '+r.asset_type,r.status,(r.source.status||'—')+' / '+(r.source.documents||0),r.queued?'PENDIENTE':r.decision||(r.source.documents?'Revisada / ver detalle':'Sin documentos capturados'),r.blocks.join(', ')||'Aplican tesis, precio, cupo y riesgo']){const td=document.createElement('td');td.textContent=text;tr.append(td)}tr.lastChild.className='reason';el('rows').append(tr)}set('count',visible.length+' de '+rows.length+' instrumentos');}el('search').addEventListener('input',draw);el('filter').addEventListener('change',draw);draw();
function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}el('json').onclick=()=>download(JSON.stringify(m,null,2),'application/json','quantia-desk-metricas.json');el('csv').onclick=()=>{const safe=x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download([['ticker','empresa','instrumento','identidad','fuente','documentos','decision','bloqueos'],...visible.map(r=>[r.ticker,r.name,r.asset_type,r.status,r.source.status,r.source.documents,r.queued?'PENDIENTE':r.decision,r.blocks.join('|')])].map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8','quantia-desk-universo.csv')};
for(const o of m.outcomes){const tr=document.createElement('tr');for(const value of [o.horizon_sessions+' ruedas',o.cohort,o.excluded??0,o.pending_anchor,o.immature,o.mature,o.evaluated,o.missing,o.mean_net_hypothetical_return_pct===null?'NO EVALUABLE':fmt(o.mean_net_hypothetical_return_pct)+'%']){const td=document.createElement('td');td.textContent=value;tr.append(td)}el('outcomes').append(tr)}
</script></body></html>'''
